select location, budget_bucket, stddev_budget from (select location, case when budget >= 3400000 then 'high' when budget >= 1668000 then 'mid' else 'low' end as budget_bucket, round(stddev(budget), 2) as stddev_budget from departments where budget between 1546000 and 3341000 group by location, case when budget >= 3400000 then 'high' when budget >= 1668000 then 'mid' else 'low' end) as sub where stddev_budget > 72;
